#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int soundex_digit(char c) {
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) { puts("EMPTY"); return 0; }
    const char *src = argv[1];
    if (src[0] == '\0') { puts("EMPTY"); return 0; }
    char out[5];
    out[0] = toupper((unsigned char)src[0]);
    out[4] = '\0';
    int prev = soundex_digit(out[0]);
    int pos = 1;
    for (size_t i = 1; src[i] && pos < 4; ++i) {
        char ch = toupper((unsigned char)src[i]);
        int d = soundex_digit(ch);
        if (d == 0) continue;
        if (d == prev) continue;
        out[pos++] = (char)('0' + d);
        prev = d;
    }
    while (pos < 4) out[pos++] = '0';
    puts(out);
    return 0;
}
